/* Première sélection de démonstration Curios. Le catalogue est extensible : chaque entrée suit le même modèle. */
window.CURIOS_COURSES = [
{id:'bm01',title:'Le monde secret des récifs coralliens',discipline:'Biologie marine',icon:'🐠',color:'#087f91',summary:'Comprendre comment se construit l’un des écosystèmes les plus riches de l’océan.',minutes:15,lead:'Sous la surface des mers tropicales, les récifs coralliens forment des paysages vivants. Ils abritent une biodiversité exceptionnelle, amortissent une partie de l’énergie des vagues et rendent de nombreux services aux sociétés côtières.',sections:[['Un animal bâtisseur','Le corail n’est ni une plante ni un rocher : c’est un animal, ou plus exactement une colonie de petits animaux appelés polypes. Chacun possède une bouche entourée de tentacules et sécrète un squelette calcaire. Au fil des générations, les squelettes s’accumulent et forment l’architecture du récif.'],['Une alliance lumineuse','De nombreux coraux vivent en association avec des microalgues, les zooxanthelles, installées dans leurs tissus. Grâce à la lumière, ces algues réalisent la photosynthèse et fournissent une partie importante de l’énergie nécessaire au corail. En échange, elles bénéficient d’un abri et de nutriments. Cette relation explique pourquoi les récifs se développent surtout dans des eaux peu profondes et claires.'],['Des villes sous-marines','Les anfractuosités du récif offrent des abris, des zones de chasse et des lieux de reproduction à une multitude d’espèces. Poissons, crustacés, mollusques, échinodermes et micro-organismes y forment des réseaux alimentaires complexes. La diversité ne se limite pas aux espèces visibles : une grande partie de la vie se cache dans les interstices du squelette.'],['Un équilibre fragile','Une hausse durable de la température de l’eau peut provoquer le blanchissement : le corail expulse alors une partie de ses algues symbiotiques et perd sa principale source d’énergie. Il n’est pas nécessairement mort, mais devient vulnérable. L’acidification de l’océan complique également la fabrication du squelette calcaire. La protection des récifs passe par la réduction des pressions locales et des émissions de gaz à effet de serre.']],fact:'Les récifs coralliens occupent une très faible part des fonds marins, mais concentrent une part remarquable de la biodiversité marine.',card:'Les récifs sont des constructions animales vivantes, édifiées lentement par des générations de polypes.',questions:[['Le corail est principalement…',['Une plante','Un animal','Un minéral'],1,'Les coraux sont des animaux appartenant au groupe des cnidaires.'],['Comment se nomment les petits animaux qui composent le corail ?',['Polypes','Planctons','Nautiles'],0,'Les polypes sont les unités vivantes de la colonie.'],['Quel est le rôle des zooxanthelles ?',['Produire du sable','Fournir de l’énergie par photosynthèse','Refroidir l’eau'],1,'Les microalgues photosynthétiques fournissent une part importante de l’énergie du corail.'],['Vrai ou faux : le blanchissement signifie toujours que le corail est déjà mort.',['Vrai','Faux'],1,'Le blanchissement est un état de stress. Le corail peut parfois récupérer si les conditions redeviennent favorables.'],['Pourquoi les récifs sont-ils importants pour les côtes ?',['Ils renforcent les vagues','Ils peuvent atténuer l’énergie des vagues','Ils empêchent toute marée'],1,'Le relief récifal dissipe une partie de l’énergie des vagues et contribue à protéger les rivages.'],['Quel phénomène rend plus difficile la fabrication du squelette calcaire ?',['L’acidification','La pleine lune','La salinité nulle'],0,'L’acidification réduit la disponibilité des ions carbonates nécessaires à la calcification.']]},
{id:'bm02',title:'Les abysses : vivre sans soleil',discipline:'Biologie marine',icon:'🌑',color:'#087f91',summary:'Explorer les grands fonds et les stratégies de vie dans l’obscurité.',minutes:16,lead:'À plusieurs milliers de mètres sous la surface, la lumière du Soleil ne parvient plus. Pourtant, les abysses ne sont pas un désert : des animaux spécialisés y vivent dans le froid, sous une pression immense et avec une nourriture souvent rare.',sections:[['Un environnement extrême','On appelle généralement grands fonds les zones océaniques situées au-delà de quelques centaines de mètres, même si les limites varient selon les disciplines. La température y est souvent proche de 2 à 4 °C. La pression augmente d’environ une atmosphère tous les dix mètres : à 4 000 mètres, elle atteint environ 400 fois la pression atmosphérique au niveau de la mer.'],['La neige marine','La plupart des écosystèmes abyssaux dépendent indirectement de la production biologique des couches éclairées. Des fragments de matière organique, des pelotes fécales et des organismes morts tombent lentement : c’est la neige marine. Cette pluie de matière nourrit des animaux filtreurs, détritivores et prédateurs. Les grandes carcasses, comme celles des baleines, créent parfois des oasis alimentaires temporaires.'],['Des adaptations étonnantes','Certains poissons possèdent une bouche extensible et un estomac capable d’accueillir de grosses proies. D’autres ont des yeux réduits ou, au contraire, très sensibles. Les organismes doivent économiser leur énergie : croissance lente, faible activité et reproduction adaptée sont fréquentes. Les corps sont généralement composés de tissus qui supportent les fortes pressions.'],['La vie sans photosynthèse','Près de certaines sources hydrothermales, des communautés reposent sur la chimiosynthèse. Des bactéries utilisent l’énergie de réactions chimiques, notamment l’oxydation de composés soufrés, pour fabriquer de la matière organique. Des vers tubicoles géants et des mollusques vivent en association avec ces bactéries. Ces écosystèmes montrent que la lumière n’est pas l’unique source d’énergie possible pour soutenir une communauté vivante.']],fact:'Les sources hydrothermales ont révélé des écosystèmes complexes fondés sur l’énergie chimique plutôt que sur la lumière solaire.',card:'Dans les abysses, la nourriture tombe souvent depuis la surface, mais certaines communautés fabriquent leur matière organique grâce à la chimiosynthèse.',questions:[['À 1 000 mètres de profondeur, la pression est approximativement…',['10 fois celle de la surface','100 fois celle de la surface','1 000 fois celle de la surface'],1,'La pression augmente d’environ une atmosphère tous les dix mètres.'],['Comment appelle-t-on les particules organiques qui tombent depuis les eaux supérieures ?',['Neige marine','Brume saline','Poussière lunaire'],0,'La neige marine transporte de la matière organique vers les profondeurs.'],['Vrai ou faux : toutes les communautés abyssales dépendent directement de la photosynthèse locale.',['Vrai','Faux'],1,'Près des sources hydrothermales, la chimiosynthèse peut soutenir la base du réseau alimentaire.'],['Quelle source d’énergie utilisent les bactéries chimiosynthétiques ?',['La lumière visible','Des réactions chimiques','Le champ magnétique'],1,'Elles tirent de l’énergie de réactions chimiques et fixent du carbone.'],['Pourquoi de nombreux animaux abyssaux économisent-ils leur énergie ?',['La nourriture est souvent rare','L’eau est toujours chaude','La lumière les épuise'],0,'La rareté des ressources favorise des stratégies de vie économes.'],['Quel événement peut créer une oasis alimentaire au fond de l’océan ?',['La chute d’une grande carcasse de baleine','Une éclipse','Une vague de chaleur atmosphérique'],0,'Une carcasse de baleine peut nourrir successivement de nombreuses espèces pendant des années.']]},
{id:'bio01',title:'La photosynthèse, moteur du vivant',discipline:'Biologie',icon:'🌿',color:'#39865c',summary:'Découvrir comment les organismes convertissent l’énergie lumineuse en énergie chimique.',minutes:15,lead:'Une grande partie de la vie sur Terre dépend d’un processus discret : la photosynthèse. Dans les feuilles, les algues et certaines bactéries, l’énergie lumineuse permet de fabriquer de la matière organique à partir de molécules minérales.',sections:[['Capturer la lumière','Chez les plantes, la photosynthèse se déroule principalement dans les chloroplastes. Ces organites contiennent des pigments, dont la chlorophylle, capables d’absorber certaines longueurs d’onde de la lumière. La couleur verte des feuilles vient en partie de la lumière verte moins absorbée et davantage réfléchie ou transmise.'],['Deux grandes étapes','Les réactions photochimiques utilisent l’énergie lumineuse pour produire des molécules énergétiques et libérer du dioxygène à partir de l’eau. Le cycle de Calvin utilise ensuite cette énergie pour intégrer le dioxyde de carbone dans des molécules organiques. Le sucre n’est donc pas simplement « fabriqué par la lumière » : il résulte d’une série de réactions biochimiques coordonnées.'],['Une histoire planétaire','Les premières formes de photosynthèse ne libéraient pas nécessairement d’oxygène. La photosynthèse oxygénique, apparue chez des ancêtres des cyanobactéries, a progressivement modifié l’atmosphère terrestre. Le grand événement d’oxydation, il y a plus de deux milliards d’années, a transformé les conditions chimiques des océans et de l’atmosphère.'],['Au-delà des plantes','Les algues et les cyanobactéries photosynthétisent aussi. Dans l’océan, le phytoplancton joue un rôle majeur dans la production primaire et les cycles du carbone. Il contribue à la production d’une part importante de l’oxygène produit chaque année, même si l’oxygène atmosphérique dépend aussi de processus géologiques et biologiques à long terme.']],fact:'La photosynthèse oxygénique a profondément transformé l’histoire de l’atmosphère terrestre.',card:'La photosynthèse convertit l’énergie lumineuse en énergie chimique et soutient une grande partie des réseaux alimentaires.',questions:[['Dans quel organite se déroule la photosynthèse chez les plantes ?',['Mitochondrie','Chloroplaste','Noyau'],1,'Les chloroplastes contiennent les pigments et les systèmes moléculaires de la photosynthèse.'],['Quel gaz est libéré lors de la photosynthèse oxygénique ?',['Azote','Dioxygène','Méthane'],1,'Le dioxygène provient de la décomposition de molécules d’eau pendant les réactions photochimiques.'],['Quel pigment absorbe fortement certaines longueurs d’onde lumineuses ?',['Chlorophylle','Mélanine','Hémoglobine'],0,'La chlorophylle est un pigment central de la capture de l’énergie lumineuse.'],['Vrai ou faux : seules les plantes réalisent la photosynthèse.',['Vrai','Faux'],1,'Les algues et les cyanobactéries photosynthétisent également.'],['Quel organisme est un acteur majeur de la photosynthèse océanique ?',['Le phytoplancton','Les étoiles de mer','Les requins'],0,'Le phytoplancton réalise une part importante de la production primaire marine.'],['Le cycle de Calvin utilise notamment…',['Le dioxyde de carbone','Le dioxygène uniquement','Le sel marin'],0,'Le cycle de Calvin fixe le carbone du CO₂ dans des molécules organiques.']]},
{id:'hist01',title:'La bibliothèque d’Alexandrie',discipline:'Histoire',icon:'🏛️',color:'#b27b35',summary:'Comprendre le projet intellectuel et le destin d’un grand centre de savoir antique.',minutes:15,lead:'La bibliothèque d’Alexandrie est devenue le symbole de la transmission des connaissances. Son histoire réelle est plus complexe que le récit d’un unique incendie qui aurait fait disparaître tout le savoir antique.',sections:[['Une capitale savante','Fondée à la fin du IVe siècle avant notre ère dans l’Égypte des Lagides, Alexandrie devient un centre politique, commercial et intellectuel majeur de la Méditerranée. Les souverains ptolémaïques soutiennent des institutions de recherche et d’enseignement associées au Mouseion, un lieu consacré aux Muses.'],['Rassembler et comparer','La bibliothèque vise à collecter des textes grecs et des œuvres venues d’autres régions. Les récits antiques évoquent des acquisitions ambitieuses, des copies et des échanges. Les savants y étudient la littérature, les mathématiques, l’astronomie, la médecine et la géographie. Le travail ne consiste pas seulement à accumuler des rouleaux : il faut aussi les classer, les comparer, les éditer et les commenter.'],['Des savants célèbres','Ératosthène, associé à Alexandrie, estime la circonférence de la Terre avec une méthode géométrique remarquable à partir de l’angle du Soleil et de la distance entre deux villes. D’autres savants, comme les grammairiens zénodote et Aristarque de Samothrace, contribuent à l’établissement critique des textes homériques.'],['Une disparition progressive','Il n’existe pas de preuve solide d’un seul incendie qui aurait détruit d’un coup l’ensemble de la bibliothèque. Plusieurs épisodes de guerre, des transformations politiques, la perte de financements et l’évolution des institutions ont probablement contribué à son déclin. La légende de la destruction totale est plus simple que la réalité historique.']],fact:'Ératosthène a estimé la circonférence terrestre plus de 1 700 ans avant les voyages de circumnavigation modernes.',card:'Alexandrie fut un centre de recherche et de transmission où les textes étaient collectés, comparés et étudiés.',questions:[['Quelle dynastie règne sur l’Égypte lors de la fondation de la bibliothèque ?',['Les Ptolémées','Les Carolingiens','Les Han'],0,'La bibliothèque se développe sous les souverains lagides, descendants de Ptolémée Ier.'],['À quelle institution le Mouseion est-il associé ?',['Un centre savant consacré aux Muses','Une école militaire','Un port commercial'],0,'Le Mouseion réunit des savants et des activités intellectuelles.'],['Quel savant est célèbre pour son estimation de la circonférence terrestre ?',['Ératosthène','Pythagore','Archimède'],0,'Ératosthène utilise notamment des mesures d’ombres et une distance connue entre deux villes.'],['Vrai ou faux : un incendie unique a certainement détruit toute la bibliothèque.',['Vrai','Faux'],1,'Les historiens privilégient une histoire complexe faite de plusieurs épisodes et transformations.'],['Quel travail les savants effectuaient-ils sur les textes ?',['Classement et comparaison','Uniquement décoration','Traduction automatique'],0,'La critique et l’établissement des textes faisaient partie du travail savant.'],['Alexandrie se situe dans quel pays actuel ?',['Égypte','Grèce','Turquie'],0,'La ville d’Alexandrie se trouve sur la côte méditerranéenne de l’Égypte.']]},
{id:'geo01',title:'Pourquoi les continents bougent-ils ?',discipline:'Géographie et géologie',icon:'🌋',color:'#7965ad',summary:'Explorer la tectonique des plaques et les mouvements lents de la surface terrestre.',minutes:16,lead:'Les continents semblent immobiles à l’échelle d’une vie humaine. Pourtant, ils se déplacent de quelques centimètres par an, portés par les plaques lithosphériques qui composent la surface rigide de la Terre.',sections:[['Une enveloppe fragmentée','La lithosphère comprend la croûte et la partie supérieure rigide du manteau. Elle est divisée en plaques qui se déplacent sur une zone plus ductile du manteau supérieur, l’asthénosphère. Les plaques portent les continents et les fonds océaniques ; elles ne correspondent donc pas exactement aux continents.'],['Trois grands types de frontières','Aux dorsales océaniques, les plaques s’écartent et de la nouvelle lithosphère océanique se forme. Dans les zones de convergence, une plaque peut plonger sous une autre : c’est la subduction, souvent associée aux séismes et au volcanisme. Lorsque deux continents entrent en collision, la croûte se raccourcit et s’épaissit, ce qui peut édifier des chaînes de montagnes.'],['Des indices convergents','La forme de certaines côtes, la répartition de fossiles identiques sur des continents aujourd’hui séparés, la continuité de roches anciennes et les mesures GPS soutiennent le mouvement des plaques. Les données magnétiques enregistrées dans les basaltes du plancher océanique ont également permis de reconstituer l’expansion des fonds marins.'],['Un mouvement lent mais puissant','Les vitesses typiques sont de l’ordre de quelques centimètres par an, comparables à la croissance des ongles. Mais sur des millions d’années, ces déplacements ouvrent des océans, ferment des bassins et rapprochent des continents. La tectonique influence les paysages, les ressources minérales, les risques naturels et le cycle du carbone à long terme.']],fact:'Les plaques tectoniques se déplacent généralement de quelques centimètres par an, une vitesse mesurable par GPS.',card:'La tectonique des plaques explique la dérive des continents, la formation des montagnes et une grande partie de l’activité sismique et volcanique.',questions:[['La lithosphère comprend…',['La croûte et le manteau supérieur rigide','Uniquement le noyau','L’atmosphère'],0,'La lithosphère est l’enveloppe externe rigide de la Terre.'],['Que se passe-t-il au niveau d’une dorsale océanique ?',['Les plaques s’écartent','Les plaques disparaissent toutes deux','Les continents cessent de bouger'],0,'La divergence permet la formation de nouvelle lithosphère océanique.'],['Comment nomme-t-on l’enfoncement d’une plaque sous une autre ?',['Subduction','Érosion','Sublimation'],0,'La subduction se produit dans certaines zones de convergence.'],['Vrai ou faux : une plaque tectonique est toujours constituée uniquement de continent.',['Vrai','Faux'],1,'Les plaques peuvent porter de la lithosphère continentale et océanique.'],['Quel outil mesure aujourd’hui directement le déplacement des plaques ?',['GPS','Thermomètre','Sismographe seul'],0,'Les réseaux GPS mesurent les déplacements relatifs de points à la surface terrestre.'],['Les vitesses habituelles des plaques sont plutôt de l’ordre de…',['Quelques centimètres par an','Plusieurs kilomètres par jour','Un mètre par seconde'],0,'Les mouvements sont lents à l’échelle humaine, mais considérables sur des millions d’années.']]},
{id:'astro01',title:'Les étoiles naissent-elles toutes de la même façon ?',discipline:'Astronomie',icon:'✨',color:'#c77a37',summary:'Suivre la naissance des étoiles dans les nuages de gaz et de poussières.',minutes:15,lead:'Les étoiles ne surgissent pas dans le vide. Elles se forment au sein de vastes nuages interstellaires, lorsque la gravité rassemble progressivement du gaz et de la poussière jusqu’à créer un cœur suffisamment dense et chaud.',sections:[['Des nuages froids','Les régions de formation stellaire se trouvent dans des nuages moléculaires riches en hydrogène. Ils sont froids à l’échelle astronomique et contiennent aussi des poussières, des molécules et des éléments plus lourds. Une perturbation, comme une onde de choc, peut favoriser l’effondrement de certaines régions du nuage.'],['La protoétoile','À mesure que la matière se contracte, elle se réchauffe et forme un cœur central : la protoétoile. La matière restante peut s’organiser en disque autour d’elle. Ce disque est aussi le lieu où des planètes peuvent se former. Des jets de matière sont parfois observés le long de l’axe de rotation du système naissant.'],['L’allumage nucléaire','Lorsque la température et la pression au cœur deviennent suffisamment élevées, la fusion de l’hydrogène en hélium peut commencer de manière durable. La pression produite par l’énergie libérée s’oppose alors à la contraction gravitationnelle. L’étoile entre dans une longue phase relativement stable appelée séquence principale.'],['Une diversité de destins','La masse initiale joue un rôle majeur. Les étoiles peu massives consomment leur combustible lentement et peuvent vivre très longtemps. Les étoiles massives sont plus lumineuses, brûlent leur combustible plus rapidement et terminent leur évolution de façon beaucoup plus spectaculaire, parfois en supernova.']],fact:'La masse d’une étoile à sa naissance détermine une grande partie de sa luminosité, de sa durée de vie et de son destin final.',card:'Les étoiles se forment par effondrement gravitationnel de nuages moléculaires, puis brillent grâce à la fusion nucléaire.',questions:[['Dans quel environnement les étoiles se forment-elles généralement ?',['Nuages moléculaires','Océans liquides','Surfaces planétaires'],0,'Les nuages moléculaires sont des réservoirs de gaz et de poussières.'],['Qu’est-ce qu’une protoétoile ?',['Une étoile en formation','Une étoile morte','Une planète géante'],0,'La protoétoile est le cœur en contraction avant la phase stable de fusion.'],['Quelle réaction alimente une étoile comme le Soleil pendant sa séquence principale ?',['Fusion de l’hydrogène en hélium','Combustion du charbon','Fission du fer'],0,'La fusion nucléaire libère l’énergie rayonnée par l’étoile.'],['Vrai ou faux : un disque autour d’une jeune étoile peut contribuer à former des planètes.',['Vrai','Faux'],0,'Les poussières et les gaz du disque protoplanétaire peuvent s’agréger.'],['Quel paramètre influence fortement le destin d’une étoile ?',['Sa masse initiale','La couleur de son nom','La distance à la Lune'],0,'La masse initiale conditionne la structure, l’évolution et la fin de vie de l’étoile.'],['Les étoiles massives ont généralement une durée de vie…',['Plus courte','Toujours plus longue','Identique à celle du Soleil'],0,'Elles consomment leur combustible beaucoup plus rapidement.']]},
{id:'phys01',title:'La lumière est-elle une onde ou une particule ?',discipline:'Physique et chimie',icon:'⚛️',color:'#627b91',summary:'Comprendre la dualité onde-particule et ce qu’elle révèle du monde quantique.',minutes:17,lead:'La lumière produit des interférences comme une onde, mais elle échange aussi son énergie par paquets appelés photons. Cette dualité n’est pas une hésitation des physiciens : elle révèle que les objets quantiques ne se décrivent pas avec les catégories de notre expérience quotidienne.',sections:[['Une onde électromagnétique','La lumière visible est une onde électromagnétique. Elle se caractérise notamment par sa longueur d’onde et sa fréquence. La lumière rouge possède une longueur d’onde plus grande que la lumière bleue. Dans le vide, toutes les ondes électromagnétiques se propagent à la même vitesse : environ 300 000 kilomètres par seconde.'],['L’expérience des fentes','Lorsqu’une lumière traverse deux fentes rapprochées, un motif d’interférences peut apparaître : certaines zones sont renforcées, d’autres atténuées. Ce comportement est typique des phénomènes ondulatoires. Des expériences réalisées avec des photons envoyés un par un montrent que le motif global se construit progressivement.'],['Des photons pour échanger l’énergie','L’effet photoélectrique montre que la lumière peut transférer son énergie par quanta. Un photon possède une énergie proportionnelle à sa fréquence. Une lumière plus intense apporte davantage de photons, tandis qu’une fréquence plus élevée augmente l’énergie de chaque photon. Cette distinction a été essentielle au développement de la physique quantique.'],['Une dualité à manier avec précision','Il ne faut pas imaginer qu’un photon est une petite bille qui se transforme parfois en vague d’eau. La mécanique quantique décrit un objet dont les résultats de mesure peuvent manifester des propriétés ondulatoires ou corpusculaires selon le dispositif expérimental. La dualité est une manière de comprendre des résultats, pas une image littérale de l’objet.']],fact:'L’énergie d’un photon augmente avec sa fréquence : les photons ultraviolets sont plus énergétiques que les photons rouges.',card:'La lumière manifeste des propriétés ondulatoires et corpusculaires selon la manière dont on l’observe.',questions:[['Quelle grandeur distingue notamment la lumière rouge de la lumière bleue ?',['La longueur d’onde','La masse du photon au repos','La gravité locale'],0,'La lumière rouge a une longueur d’onde plus grande que la lumière bleue.'],['Que révèle un motif d’interférences ?',['Un comportement ondulatoire','Une réaction chimique','Une attraction magnétique'],0,'Les interférences sont caractéristiques de la superposition d’ondes.'],['L’énergie d’un photon est proportionnelle à…',['Sa fréquence','Sa couleur préférée','La distance à la Terre'],0,'La relation de Planck relie l’énergie d’un photon à sa fréquence.'],['Vrai ou faux : une lumière plus intense signifie nécessairement que chaque photon est plus énergétique.',['Vrai','Faux'],1,'L’intensité correspond notamment au nombre de photons ; l’énergie individuelle dépend de la fréquence.'],['Quelle expérience a joué un rôle important dans la compréhension quantique de la lumière ?',['L’effet photoélectrique','La chute des corps','La dérive des continents'],0,'L’effet photoélectrique montre l’échange d’énergie par quanta.'],['Dans le vide, les différentes couleurs de lumière se déplacent…',['À la même vitesse','À des vitesses toujours différentes','Sans se déplacer'],0,'Toutes les ondes électromagnétiques se propagent à la vitesse de la lumière dans le vide.']]},
{id:'myth01',title:'Le mythe de Prométhée',discipline:'Mythologie',icon:'🔥',color:'#a76b9b',summary:'Découvrir le récit grec du feu volé aux dieux et ses interprétations.',minutes:14,lead:'Dans la mythologie grecque, Prométhée est un Titan associé à l’intelligence et à la ruse. Son geste le plus célèbre consiste à voler le feu aux dieux pour le donner aux humains, un acte qui entraîne une terrible punition.',sections:[['Un bien réservé aux dieux','Dans plusieurs versions du mythe, Prométhée intervient en faveur des humains face à Zeus. Le feu représente bien davantage qu’une flamme : il symbolise la technique, la cuisson, l’artisanat et la possibilité de transformer le monde. Donner le feu, c’est donner aux humains un moyen d’agir sur leur environnement.'],['La ruse et le sacrifice','Prométhée est aussi associé à un épisode où il trompe Zeus lors du partage d’un sacrifice. Les humains obtiennent une part avantageuse, tandis que les dieux reçoivent les os recouverts de graisse. Le récit propose ainsi une explication mythique de pratiques rituelles et de la relation entre humains et divinités.'],['Le châtiment','Pour punir Prométhée, Zeus le fait enchaîner à un rocher. Un aigle vient dévorer son foie, qui se régénère, répétant sans fin la souffrance. Héraclès le délivre dans certaines traditions. Le supplice exprime le conflit entre la puissance divine et la transgression du Titan.'],['Un symbole toujours actuel','Au fil des siècles, Prométhée devient une figure de la connaissance, du progrès et de la révolte contre les limites imposées. Mais le mythe peut aussi être lu comme une mise en garde : une technique puissante apporte des possibilités nouvelles, mais aussi des responsabilités.']],fact:'Le mot « prométhéen » désigne souvent une ambition audacieuse, tournée vers la maîtrise ou la transformation du monde.',card:'Prométhée incarne à la fois la transmission du savoir technique et le prix de la transgression.',questions:[['Que donne Prométhée aux humains dans le récit le plus célèbre ?',['Le feu','L’immortalité','La mer'],0,'Le feu symbolise la technique et la transformation du monde.'],['Qui punit Prométhée ?',['Zeus','Poséidon','Hermès'],0,'Zeus ordonne le supplice du Titan.'],['Quel animal dévore le foie de Prométhée ?',['Un aigle','Un lion','Un serpent marin'],0,'L’aigle revient chaque jour dans le récit du châtiment.'],['Vrai ou faux : le foie de Prométhée se régénère dans le mythe.',['Vrai','Faux'],0,'La régénération rend le supplice répétitif et sans fin.'],['Quel thème moderne est souvent associé à Prométhée ?',['Le progrès technique','La navigation polaire','La fondation de Rome'],0,'Prométhée est devenu un symbole de connaissance, de technique et de défi.'],['Prométhée appartient à quelle famille divine ?',['Les Titans','Les Olympiens uniquement','Les héros mortels'],0,'Prométhée est un Titan dans la mythologie grecque.']]},
{id:'med01',title:'Le système immunitaire : une défense coordonnée',discipline:'Corps humain et médecine',icon:'🛡️',color:'#b85f78',summary:'Comprendre comment l’organisme détecte et combat les agents infectieux.',minutes:16,lead:'Le système immunitaire n’est pas une simple armée de cellules. C’est un réseau complexe d’organes, de tissus, de molécules et de cellules qui distingue de nombreux signaux et coordonne des réponses adaptées.',sections:[['Des barrières en première ligne','La peau, les muqueuses, le mucus, les larmes et certaines substances chimiques limitent l’entrée des agents infectieux. Le microbiote participe également à la protection en occupant des niches écologiques et en interagissant avec les défenses de l’organisme. Ces mécanismes constituent une première ligne de défense.'],['L’immunité innée','Présente dès la naissance, l’immunité innée agit rapidement. Des cellules comme les macrophages et les neutrophiles reconnaissent des motifs associés aux microbes et peuvent les englober par phagocytose. L’inflammation attire des cellules et des molécules de défense vers la zone concernée. Cette réponse est rapide, mais sa reconnaissance est moins spécifique que celle de l’immunité adaptative.'],['L’immunité adaptative','Les lymphocytes B peuvent produire des anticorps, tandis que les lymphocytes T jouent plusieurs rôles, notamment la coordination de la réponse ou la destruction de cellules infectées. Les récepteurs des lymphocytes reconnaissent des fragments moléculaires précis. Après une première rencontre, certaines cellules deviennent des cellules mémoire.'],['La mémoire immunitaire','Lors d’une nouvelle exposition au même agent, la réponse peut être plus rapide et plus efficace. La vaccination exploite ce principe en présentant au système immunitaire un antigène ou des instructions permettant de le produire, sans provoquer la maladie visée dans les conditions attendues. Les vaccins entraînent ainsi une mémoire protectrice, dont la durée varie selon les maladies et les vaccins.']],fact:'La vaccination prépare le système immunitaire à reconnaître un agent infectieux avant une exposition réelle.',card:'L’immunité combine des barrières, une réponse innée rapide et une réponse adaptative capable de mémoire.',questions:[['Quel organe constitue une barrière physique majeure contre les microbes ?',['La peau','Le pancréas','La thyroïde'],0,'La peau forme une barrière protectrice, renforcée par des mécanismes chimiques et biologiques.'],['Quelle cellule peut réaliser la phagocytose ?',['Macrophage','Globule rouge mature','Cellule osseuse'],0,'Les macrophages peuvent englober et digérer des agents étrangers.'],['Quel élément produit des anticorps ?',['Lymphocyte B activé','Plaquette sanguine','Neurone'],0,'Les lymphocytes B peuvent se différencier en cellules productrices d’anticorps.'],['Vrai ou faux : l’immunité innée est généralement plus rapide que l’immunité adaptative.',['Vrai','Faux'],0,'L’immunité innée agit rapidement, tandis que la réponse adaptative spécifique se met en place plus lentement lors du premier contact.'],['Sur quel principe repose la mémoire immunitaire ?',['Une réponse améliorée lors d’une nouvelle exposition','La disparition de tous les globules blancs','L’arrêt de l’inflammation pour toujours'],0,'Des cellules mémoire persistent après une première rencontre avec un antigène.'],['La vaccination vise notamment à…',['Préparer le système immunitaire','Remplacer les globules rouges','Détruire le microbiote'],0,'La vaccination entraîne une réponse immunitaire et une mémoire protectrice.']]},
{id:'tech01',title:'Comment fonctionne Internet ?',discipline:'Technologies',icon:'🌐',color:'#357d9c',summary:'Suivre le trajet des données entre appareils, routeurs et serveurs.',minutes:15,lead:'Internet n’est pas un nuage mystérieux : c’est un réseau mondial de réseaux reliés par des câbles, des fibres optiques, des équipements radio et des routeurs. Les informations y circulent sous forme de paquets de données.',sections:[['Un réseau de réseaux','Chaque appareil connecté rejoint un réseau local ou un réseau d’accès. Les fournisseurs d’accès relient ces réseaux à d’autres réseaux, jusqu’à former une infrastructure mondiale. Les câbles sous-marins transportent une grande partie du trafic intercontinental ; les satellites jouent aussi un rôle, notamment pour certaines zones isolées.'],['Des paquets qui voyagent','Lorsqu’un message est envoyé, les données sont découpées en paquets. Chaque paquet contient des informations nécessaires à son acheminement. Les routeurs lisent les adresses réseau et choisissent une route vers la destination. Les paquets peuvent emprunter des chemins différents puis être réassemblés à l’arrivée.'],['Adresses et noms de domaine','Les appareils utilisent des adresses IP pour communiquer. Comme ces suites de chiffres sont difficiles à mémoriser, le système DNS traduit les noms de domaine en adresses IP. Le navigateur peut ensuite contacter le serveur hébergeant le site demandé.'],['Des protocoles communs','Les protocoles définissent les règles de communication. IP participe à l’adressage et au routage, TCP assure notamment une transmission fiable dans de nombreux usages, et HTTP sert aux échanges du Web. HTTPS ajoute une couche de sécurité grâce au chiffrement TLS. Internet et le Web sont liés, mais ne sont pas synonymes : le Web est un service qui fonctionne sur Internet.']],fact:'Le Web n’est qu’un des services d’Internet : le courrier électronique et d’autres applications utilisent aussi cette infrastructure.',card:'Internet relie des réseaux grâce à des protocoles communs ; les données sont acheminées sous forme de paquets.',questions:[['Internet est avant tout…',['Un réseau de réseaux','Un seul ordinateur géant','Un logiciel unique'],0,'Internet est une infrastructure mondiale reliant de nombreux réseaux.'],['Quel équipement oriente les paquets vers leur destination ?',['Routeur','Écran','Clavier'],0,'Les routeurs acheminent les paquets entre réseaux.'],['À quoi sert principalement le DNS ?',['Associer des noms de domaine à des adresses IP','Chiffrer toutes les photos','Augmenter la mémoire vive'],0,'Le DNS permet de retrouver l’adresse IP associée à un nom de domaine.'],['Vrai ou faux : le Web et Internet désignent exactement la même chose.',['Vrai','Faux'],1,'Le Web est un service qui fonctionne sur l’infrastructure Internet.'],['Que signifie le S de HTTPS dans l’usage courant ?',['Sécurisé','Satellite','Synchronisé'],0,'HTTPS utilise TLS pour protéger les échanges entre navigateur et serveur.'],['Comment les données sont-elles souvent découpées pour circuler ?',['En paquets','En images uniquement','En ondes sonores'],0,'La commutation par paquets permet d’acheminer des fragments de données.']]},
{id:'art01',title:'La perspective dans la peinture',discipline:'Arts et littérature',icon:'🖼️',color:'#a66b8c',summary:'Comprendre comment les artistes représentent la profondeur sur une surface plane.',minutes:14,lead:'Une toile est plate, mais elle peut donner l’impression d’ouvrir une fenêtre sur un espace profond. La perspective rassemble plusieurs techniques qui organisent les formes, les lignes et les couleurs pour produire une illusion spatiale.',sections:[['La perspective linéaire','Dans une représentation en perspective centrale, les lignes parallèles dans la réalité peuvent converger vers un ou plusieurs points de fuite. La ligne d’horizon correspond approximativement au niveau des yeux du spectateur. Les objets semblent plus petits lorsqu’ils sont représentés plus loin.'],['Une innovation de la Renaissance','Les artistes et théoriciens de la Renaissance italienne codifient des méthodes géométriques de représentation de l’espace. Filippo Brunelleschi est souvent associé aux premières démonstrations de perspective linéaire, tandis que Leon Battista Alberti en expose les principes dans son traité De pictura au XVe siècle.'],['La profondeur par la couleur','La perspective atmosphérique utilise les effets de l’air entre le spectateur et les objets lointains. Les contrastes diminuent, les contours deviennent moins nets et les couleurs tendent souvent vers des tons plus froids ou bleutés. Cette technique ne repose pas sur des lignes géométriques, mais sur l’observation de la perception.'],['Une convention parmi d’autres','La perspective linéaire n’est pas la seule manière de représenter l’espace. De nombreuses traditions artistiques utilisent des perspectives multiples, des tailles symboliques ou des organisations non réalistes. Le choix d’une perspective dépend d’une intention artistique et culturelle : représenter un espace crédible n’est pas l’unique objectif de l’art.']],fact:'La perspective atmosphérique crée de la profondeur en diminuant les contrastes et la netteté des éléments éloignés.',card:'La perspective est un ensemble de procédés qui permettent de suggérer la profondeur sur une surface plane.',questions:[['Dans la perspective linéaire, les lignes parallèles peuvent converger vers…',['Un point de fuite','Le centre du tableau obligatoirement','Le cadre uniquement'],0,'Le point de fuite organise la convergence apparente de certaines lignes.'],['À quoi correspond la ligne d’horizon dans une perspective centrale ?',['Au niveau des yeux du spectateur','Au bord inférieur du cadre','À la limite de la toile'],0,'La ligne d’horizon est liée à la hauteur du regard.'],['Quel traité est associé à Leon Battista Alberti ?',['De pictura','La République','L’Origine des espèces'],0,'Alberti expose des principes de perspective dans De pictura.'],['Vrai ou faux : toutes les traditions artistiques utilisent la perspective linéaire.',['Vrai','Faux'],1,'Les artistes ont développé de nombreuses manières de représenter l’espace.'],['La perspective atmosphérique joue notamment sur…',['Les contrastes et la netteté','Le poids du cadre','Le nombre de personnages'],0,'Les objets lointains apparaissent souvent moins contrastés et moins nets.'],['Quel artiste est souvent associé aux premières démonstrations de perspective linéaire ?',['Filippo Brunelleschi','Claude Monet','Pablo Picasso'],0,'Brunelleschi est fréquemment cité dans l’histoire de la perspective renaissante.']]},
{id:'eco01',title:'Pourquoi les saisons existent-elles ?',discipline:'Sciences de la Terre',icon:'🌍',color:'#568b78',summary:'Distinguer l’inclinaison de l’axe terrestre de la distance au Soleil.',minutes:13,lead:'Les saisons ne sont pas causées principalement par la distance entre la Terre et le Soleil. Elles résultent de l’inclinaison de l’axe de rotation terrestre, qui modifie la hauteur du Soleil dans le ciel et la durée du jour au fil de l’année.',sections:[['Un axe incliné','L’axe de rotation de la Terre est incliné d’environ 23,4 degrés par rapport à la perpendiculaire au plan de son orbite. Pendant une partie de l’année, l’hémisphère Nord est incliné vers le Soleil ; six mois plus tard, c’est l’hémisphère Sud.'],['L’énergie reçue varie','Quand un hémisphère est incliné vers le Soleil, les rayons arrivent plus directement et les journées sont plus longues. Une même quantité d’énergie se répartit alors sur une surface plus petite et pendant une durée quotidienne plus importante. En hiver, le Soleil est plus bas et les journées plus courtes : l’énergie reçue par unité de surface diminue.'],['Des saisons inversées','Lorsque c’est l’été dans l’hémisphère Nord, c’est l’hiver dans l’hémisphère Sud. Les équinoxes correspondent aux périodes où la durée du jour et de la nuit est approximativement égale dans la plupart des régions. Les solstices marquent les journées les plus longues ou les plus courtes de l’année selon l’hémisphère.'],['Et la distance au Soleil ?','La Terre est légèrement plus proche du Soleil au début du mois de janvier qu’au début du mois de juillet. Cette variation n’explique pas les saisons : si elle était déterminante, les deux hémisphères connaîtraient les mêmes saisons au même moment. L’inclinaison explique au contraire leur opposition.']],fact:'La Terre est proche de son périhélie en janvier : c’est pourtant l’hiver dans l’hémisphère Nord.',card:'Les saisons sont dues à l’inclinaison de l’axe terrestre, qui fait varier l’angle des rayons solaires et la durée du jour.',questions:[['Quelle est la cause principale des saisons ?',['L’inclinaison de l’axe terrestre','La distance Terre-Lune','Les vents dominants'],0,'L’inclinaison modifie l’ensoleillement reçu par chaque hémisphère.'],['Quel est l’angle approximatif de l’inclinaison de l’axe terrestre ?',['23,4°','5°','90°'],0,'L’axe terrestre est incliné d’environ 23,4 degrés par rapport à la perpendiculaire au plan orbital.'],['Quand c’est l’été dans l’hémisphère Nord, c’est généralement…',['L’hiver dans l’hémisphère Sud','L’été partout','Le printemps partout'],0,'Les saisons sont opposées entre les deux hémisphères.'],['Vrai ou faux : la Terre est plus proche du Soleil en janvier qu’en juillet.',['Vrai','Faux'],0,'Le périhélie se produit au début de janvier, sans provoquer l’été boréal.'],['Que caractérise un équinoxe ?',['Une durée du jour et de la nuit proche de l’égalité','Le jour le plus long partout','La distance minimale au Soleil'],0,'Aux équinoxes, la durée du jour et de la nuit est approximativement égale.'],['En été, le Soleil est généralement…',['Plus haut dans le ciel et visible plus longtemps','Plus bas et visible moins longtemps','Absent la nuit entière partout'],0,'L’angle solaire plus élevé et les journées plus longues augmentent l’énergie reçue.']]},
{id:'bio02',title:'Les champignons : ni plantes ni animaux',discipline:'Biologie',icon:'🍄',color:'#39865c',summary:'Découvrir un règne essentiel au fonctionnement des écosystèmes.',minutes:14,lead:'Les champignons sont parfois confondus avec les plantes parce qu’ils poussent au sol et restent souvent immobiles. Pourtant, ils forment une lignée évolutive distincte, plus proche des animaux que des plantes.',sections:[['Un règne à part','Les champignons appartiennent au règne des Fungi. Ils ne possèdent pas de chlorophylle et ne réalisent pas la photosynthèse. Ils obtiennent leurs nutriments en absorbant des molécules organiques après les avoir décomposées à l’extérieur de leurs cellules grâce à des enzymes.'],['Le réseau du mycélium','Le corps de nombreux champignons est constitué de filaments microscopiques appelés hyphes. Leur ensemble forme le mycélium, souvent caché dans le sol, le bois ou un autre substrat. Le champignon visible, comme un chapeau, est généralement une structure reproductrice produisant des spores.'],['Décomposeurs et partenaires','De nombreux champignons décomposent le bois et la matière organique morte, contribuant au recyclage du carbone et des nutriments. D’autres vivent en symbiose avec les racines des plantes : les mycorhizes facilitent notamment l’absorption de certains minéraux et de l’eau, tandis que la plante fournit des sucres au champignon.'],['Une diversité d’usages','Les levures sont des champignons unicellulaires utilisées dans la fermentation. Certaines moisissures participent à la fabrication de fromages ou à la production de médicaments. D’autres champignons provoquent des maladies ou produisent des toxines. Leur diversité impose donc de distinguer les espèces et de ne jamais consommer un champignon sauvage sans identification certaine par une personne compétente.']],fact:'Le « champignon » visible en forêt n’est souvent que la partie reproductrice d’un organisme dont le mycélium est caché.',card:'Les champignons absorbent les nutriments, décomposent la matière et nouent des symbioses essentielles avec les plantes.',questions:[['Les champignons appartiennent au règne…',['Fungi','Plantae','Animalia'],0,'Les champignons constituent un règne distinct, celui des Fungi.'],['Comment se nomme le réseau de filaments du champignon ?',['Mycélium','Chloroplaste','Pistil'],0,'Le mycélium est constitué d’hyphes.'],['Pourquoi les champignons ne sont-ils pas des plantes ?',['Ils ne réalisent pas la photosynthèse','Ils sont toujours mobiles','Ils n’ont pas de cellules'],0,'Les champignons sont hétérotrophes et absorbent des nutriments.'],['Vrai ou faux : le chapeau visible représente toujours l’ensemble du champignon.',['Vrai','Faux'],1,'Le chapeau est généralement une structure reproductrice ; le mycélium constitue une grande partie de l’organisme.'],['Comment appelle-t-on l’association entre un champignon et les racines d’une plante ?',['Mycorhize','Lichen uniquement','Pollinisation'],0,'Les mycorhizes sont des symbioses entre champignons et racines.'],['Quel rôle écologique majeur jouent de nombreux champignons ?',['Décomposer la matière organique','Produire la lumière solaire','Créer l’azote atmosphérique'],0,'La décomposition permet de recycler les nutriments dans les écosystèmes.']]},
{id:'hist02',title:'La route de la soie : un réseau, pas une route',discipline:'Histoire',icon:'🐫',color:'#b27b35',summary:'Comprendre les échanges qui reliaient l’Asie, le Moyen-Orient et l’Europe.',minutes:15,lead:'L’expression « route de la soie » évoque une piste unique traversant les déserts. En réalité, elle désigne un ensemble de routes terrestres et maritimes, de relais et de villes marchandes qui ont relié différentes régions d’Eurasie pendant des siècles.',sections:[['Des itinéraires multiples','Les échanges se développent par étapes et changent selon les périodes, les pouvoirs politiques, les guerres et les conditions commerciales. Des caravanes traversent les oasis d’Asie centrale, tandis que des routes maritimes relient les ports de l’océan Indien, de la mer Rouge et de la Méditerranée.'],['Bien plus que de la soie','La soie est un produit prestigieux, mais les échanges concernent aussi les épices, les pierres précieuses, les métaux, les chevaux, le papier, les textiles et les savoir-faire. Les marchands transportent également des idées, des techniques, des langues et des pratiques religieuses.'],['Des villes carrefours','Des villes comme Samarcande deviennent des lieux de rencontre entre marchands, artisans, diplomates et voyageurs. Les oasis sont essentielles : elles offrent de l’eau, des marchés et des lieux de repos. Les réseaux marchands dépendent donc autant des infrastructures et de la confiance que des marchandises elles-mêmes.'],['Des circulations culturelles','Le bouddhisme, l’islam, le christianisme et d’autres traditions circulent par des itinéraires différents. Les techniques de fabrication du papier se diffusent progressivement vers l’ouest. Les échanges ne sont pas toujours pacifiques : conquêtes, prélèvements et conflits accompagnent aussi ces circulations.']],fact:'La « route de la soie » est une expression moderne qui résume des réseaux commerciaux très variés et changeants.',card:'Les routes de la soie formaient un vaste réseau d’échanges matériels, techniques et culturels à travers l’Eurasie.',questions:[['La route de la soie était…',['Un réseau de routes terrestres et maritimes','Une seule piste rectiligne','Une voie ferrée antique'],0,'Les itinéraires variaient selon les périodes et les régions.'],['Quel produit a donné son nom à ce réseau ?',['La soie','Le poivre','Le papier'],0,'La soie était un produit prestigieux échangé sur de longues distances.'],['Quel rôle jouaient les oasis ?',['Fournir eau, repos et marchés','Empêcher les échanges','Produire des navires'],0,'Les oasis étaient des étapes essentielles dans les régions arides.'],['Vrai ou faux : seuls des objets circulaient sur ces routes.',['Vrai','Faux'],1,'Des idées, des techniques, des religions et des savoir-faire circulaient aussi.'],['Quelle ville d’Asie centrale est un important carrefour historique ?',['Samarcande','Reykjavik','Lisbonne'],0,'Samarcande est une ville majeure des échanges en Asie centrale.'],['La diffusion du papier vers l’ouest est liée notamment…',['Aux échanges eurasiatiques','À la conquête de l’Antarctique','À l’invention de l’imprimerie numérique'],0,'Les techniques de fabrication du papier se diffusent progressivement à travers les réseaux d’échanges.']]},
{id:'bio03',title:'Le langage des abeilles',discipline:'Biologie',icon:'🐝',color:'#39865c',summary:'Découvrir comment les abeilles indiquent la direction et la distance d’une ressource.',minutes:14,lead:'Lorsqu’une abeille domestique découvre une source de nourriture, elle peut revenir à la ruche et transmettre des informations à ses congénères. Sa danse transforme une expérience individuelle en indication exploitable par la colonie.',sections:[['Une danse sur le rayon','La danse frétillante est réalisée sur les rayons de la ruche. L’abeille effectue une trajectoire en forme de huit, avec une phase rectiligne accompagnée de vibrations de l’abdomen. L’orientation de cette phase fournit une information sur la direction de la ressource par rapport à la position du Soleil.'],['Direction et distance','L’angle de la danse par rapport à la verticale du rayon correspond à l’angle de la ressource par rapport au Soleil. La durée de la phase frétillante est liée à la distance parcourue. Les abeilles qui observent la danse peuvent ainsi estimer où chercher. La précision dépend des conditions et de la qualité de l’information.'],['Une communication collective','La danse ne transmet pas une carte complète : elle donne des indications que les autres abeilles doivent interpréter et vérifier en volant. Les odeurs de la ressource, les repères visuels et l’expérience individuelle contribuent aussi à la recherche. La colonie combine donc plusieurs formes d’information.'],['Une découverte scientifique','Karl von Frisch a étudié ce comportement et contribué à démontrer sa fonction communicative. Ses travaux ont été récompensés par le prix Nobel de physiologie ou médecine en 1973, partagé avec Konrad Lorenz et Nikolaas Tinbergen, pour leurs découvertes sur l’organisation et le déclenchement des comportements individuels et sociaux.']],fact:'L’orientation de la danse est référencée par rapport à la position du Soleil, même lorsque l’abeille danse sur un rayon vertical.',card:'La danse frétillante transmet aux autres abeilles des informations sur la direction et la distance d’une ressource.',questions:[['Quelle danse indique la direction et la distance d’une ressource ?',['La danse frétillante','La danse circulaire de parade','La danse du sommeil'],0,'La danse frétillante fournit des informations spatiales.'],['À quoi correspond l’angle de la phase rectiligne ?',['À la direction de la ressource par rapport au Soleil','À la température du miel','À l’âge de la reine'],0,'L’orientation est codée par rapport à la verticale et à la position solaire.'],['La durée de la phase frétillante est liée notamment…',['À la distance','À la couleur des fleurs uniquement','Au nombre de pattes'],0,'La durée de la phase frétillante augmente avec la distance de la ressource.'],['Vrai ou faux : les abeilles utilisent uniquement la danse pour trouver les fleurs.',['Vrai','Faux'],1,'Les odeurs, les repères visuels et l’expérience participent aussi à la recherche.'],['Quel chercheur est célèbre pour ses travaux sur la danse des abeilles ?',['Karl von Frisch','Louis Pasteur','Charles Darwin'],0,'Karl von Frisch a démontré la fonction communicative de la danse.'],['Le prix Nobel de von Frisch date de…',['1973','1901','2010'],0,'Il reçoit le prix Nobel en 1973 avec Lorenz et Tinbergen.']]}
];
